using System.Net;
using System.Text;
using System.Text.Json.Nodes;
using Orbit.Core;
static class QuickLoaderChecks {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 sealed class Fake:HttpMessageHandler {public string Xml="<metadata><versioning><versions><version>1.21.1-52.1.0</version><version>1.7.10-10.13.4.1614-1.7.10</version></versions></versioning></metadata>";protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){string url=request.RequestUri!.ToString();string body=url.Contains("meta.fabricmc.net")?"[{\"loader\":{\"version\":\"0.99-beta\",\"stable\":false}},{\"loader\":{\"version\":\"0.20.0\",\"stable\":true}}]":url.Contains("promotions_slim")?"{\"promos\":{\"1.21.1-recommended\":\"52.1.0\",\"1.21.1-latest\":\"52.1.20\",\"1.7.10-recommended\":\"10.13.4.1614\"}}":Xml;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(body)});}}
 public static async Task<int> Run(string root){try{root=Path.Combine(Path.GetFullPath(root),Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);using var service=new QuickLoader(new Fake());Check(await service.ResolveVersionAsync("1.21.1","Fabric")=="0.20.0","Fabric chooses stable build before a beta");Check(await service.ResolveVersionAsync("1.21.1","Forge")=="52.1.0","Forge chooses recommended official build");Check(await service.ResolveVersionAsync("1.7.10","Forge")=="10.13.4.1614-1.7.10","Legacy Forge Maven build suffix retained");bool rejected=false;try{await service.ResolveVersionAsync("../escape","Forge");}catch(InvalidDataException){rejected=true;}Check(rejected,"Minecraft traversal rejected before network access");using(var bad=new QuickLoader(new Fake{Xml="<!DOCTYPE foo [<!ENTITY xxe SYSTEM 'file:///not-allowed'>]><metadata>&xxe;</metadata>"})){rejected=false;try{await bad.ResolveVersionAsync("1.21.1","Forge");}catch(System.Xml.XmlException){rejected=true;}Check(rejected,"Forge XML external entities rejected");}
 foreach(string loader in new[]{"Forge","Fabric","Vanilla"}){var v=new VersionEntry("fixture",loader,"1.21.1",21);Check(v.VisualKind==(loader=="Forge"?"forge":loader=="Fabric"?"fabric":"installed"),loader+" identity has precedence over installed state");Check(v.RailLabel.Contains("1.21.1")&&v.RailLabel.Contains(loader),loader+" sidebar label includes Minecraft and loader");}
 Check(new VersionEntry("remote","Vanilla","1.21.1",21){Installed=false}.VisualKind=="available","Uninstalled vanilla stays distinct from green installed version");Check(new LauncherSettings().Theme=="brawl stars","Fresh settings use the renamed Default lobby");
 string legacyDir=Path.Combine(root,"legacy","versions","ForgeOptiFine 1.12.2");Directory.CreateDirectory(legacyDir);File.WriteAllText(Path.Combine(legacyDir,"ForgeOptiFine 1.12.2.json"),"{\"mainClass\":\"net.minecraftforge.LegacyMain\",\"libraries\":[]}");Check(Versions.Scan(Path.Combine(root,"legacy")).Single().BaseVersion=="1.12.2","Standalone legacy Forge profile resolves the real Minecraft version");
 string source=Path.Combine(root,"source"),dest=Path.Combine(root,"destination");Directory.CreateDirectory(source);Directory.CreateDirectory(dest);File.WriteAllText(Path.Combine(source,"lib.jar"),"fixture");File.WriteAllText(Path.Combine(dest,"launcher_profiles.json"),"private-profile-sentinel");QuickLoader.Promote(source,dest,CancellationToken.None);Check(File.ReadAllText(Path.Combine(dest,"lib.jar"))=="fixture","Loader library promotion preserves bytes");Check(File.ReadAllText(Path.Combine(dest,"launcher_profiles.json"))=="private-profile-sentinel","Existing launcher profiles remain untouched");QuickLoader.Promote(source,dest,CancellationToken.None);Check(Directory.GetFiles(dest,"*.tmp").Length==0,"Repeated promotion is idempotent and leaves no temporary files");File.WriteAllText(Path.Combine(source,"lib.jar"),"changed");rejected=false;try{QuickLoader.Promote(source,dest,CancellationToken.None);}catch(IOException){rejected=true;}Check(rejected&&File.ReadAllText(Path.Combine(dest,"lib.jar"))=="fixture","Conflict preserves installed library");using var cancel=new CancellationTokenSource();cancel.Cancel();bool cancelled=false;try{QuickLoader.Promote(source,Path.Combine(root,"cancel"),cancel.Token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&!Directory.Exists(Path.Combine(root,"cancel")),"Cancellation publishes no loader files");Console.WriteLine($"PASS {count} quick-loader checks; no game launched.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 public static async Task<int> Live(string root,string minecraftRoot){try{root=Path.Combine(Path.GetFullPath(root),"live-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string baseDir=Path.Combine(root,"versions","1.21.1");Directory.CreateDirectory(baseDir);foreach(string ext in new[]{".json",".jar"})File.Copy(Path.Combine(minecraftRoot,"versions","1.21.1","1.21.1"+ext),Path.Combine(baseDir,"1.21.1"+ext));File.WriteAllText(Path.Combine(root,"launcher_profiles.json"),"private-profile-sentinel");using var service=new QuickLoader();foreach(string loader in new[]{"Fabric","Forge"}){string version=await service.ResolveVersionAsync("1.21.1",loader);Console.WriteLine("INSTALL "+loader+" "+version+" in private fixture root");using var timeout=new CancellationTokenSource(TimeSpan.FromMinutes(8));string id=await service.InstallPreparedAsync(root,"1.21.1",loader,version,null,timeout.Token,minecraftRoot);var profile=Versions.Resolve(root,id);Check(profile.Chain.Contains("1.21.1")&&Versions.Scan(root).Any(v=>v.Id==id&&v.Loader==loader),loader+" real installer produces correctly identified inherited profile");Check(profile.MainClass!=Versions.Resolve(root,"1.21.1").MainClass,loader+" has its real loader entry point");Check(File.ReadAllText(Path.Combine(root,"launcher_profiles.json"))=="private-profile-sentinel",loader+" does not modify pre-existing launcher profiles");Check(!Directory.EnumerateDirectories(Path.Combine(root,".orbit-loader-staging")).Any(),loader+" staging is cleaned after success");Console.WriteLine("PROFILE "+id+" libraries "+profile.Libraries.Count);}
 Console.WriteLine("PASS live Fabric and Forge install; Java installer ran, Minecraft did not run. "+root);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
